-- ============================================================================
-- H5: Quantitative Risk Assessment joins the catalogue, the FIFTH and last
-- course of the HSE module.
--
-- Catalogue row (module 'hse'; path_order 65, above H4 consequence at 64 and H3
-- lopa at 63; prereq_slug NULL, the carried-over answer "no hard prerequisite
-- inside a module"; school left at its default, as every HSE course leaves it,
-- so the fees are the published school-level rows) plus the three capstones and
-- their eighteen graded fields, generated by tools/course-waves/qra/gen_course.py
-- from the ENGINE'S OWN RUN (h5_capstone.mjs through the vendored
-- engines/hse/qra.js), which it refuses to write unless fields.json carries
-- exactly that run's values and the tolerance gradedTolerance.js derives. Deep
-- seeds are three separate migrations; the go-live is a fifth and is HELD until
-- a NextGen production upload carries the route /dashboard/apps/qra, because
-- the 78 lessons, the teaching lab (qraLab.js) and its three explorer panels
-- ship in the zip and not in this database.
--
-- THE ONE SENTENCE THE COURSE IS. A quantitative risk assessment turns scenario
-- frequencies and probabilities of death into one person's individual risk, a
-- population's societal risk and a test of whether a further measure is
-- reasonably practicable, so the course teaches how often and what one person
-- carries (Associate), how many die at once (Professional), and whether a
-- further measure is reasonably practicable and what the engine does not know
-- (Expert), and grades each tier on its own question with numbers the engine
-- returns.
--
-- THE ENGINE. engines/hse/qra.js at the canonical pin petrolord-engines
-- 16fd6c9. Nothing is invented: every frequency, probability, probability of
-- death, occupancy, VPF, DF and rate is an input. Every branch set sums to one
-- within 1e-9; F(N) is the frequency of N or more deaths; a value exactly at a
-- threshold belongs to the lower band; present values are year-end; the ICAF
-- counts fatalities prevented undiscounted.
--
-- WHAT IS GRADED. UKPOKITI (Associate) grades two event tree outcome
-- frequencies, two LSIRs and two IRPAs; OGINI (Professional) grades a crew's
-- PLL and FAR, a village's frequency of ten or more deaths, its worst ratio to
-- the Dutch line, where it exceeds on a stated step, and its ratio to the R2P2
-- point; EBUGHU (Expert) grades cost to benefit ratios, ICAFs and the largest
-- reasonably practicable cost of three measures under stated discounting.
-- Every value is a return value of the engine, and every prompt is rendered
-- from the inputs the engine was run on. Every probability of death and every
-- expected number of deaths is stated: producing one belongs to the
-- consequence course, which this course never grades.
--
-- All eighteen graded values were swept against every number the digest
-- prints and against every number handed to a learner in a prompt, at each
-- field's own shipped tolerance: 0 collisions, and 0 pairwise. No prompt
-- states another tier's graded value.
-- ============================================================================

insert into public.academy_apps (slug, name, module, path_order, status, prereq_slug)
values ('qra', 'Quantitative Risk Assessment', 'hse', 65, 'coming_soon', null)
on conflict (slug) do nothing;

insert into public.academy_capstones
    (app_slug, tier, cert_tier, dataset, title, prompt, fields)
values
(
  'qra', 'beginner', 'associate',
  'UKPOKITI, an onshore gas compression station and its camp',
  'How often each outcome happens, and what one person carries',
  'UKPOKITI, an onshore gas compression station with a workers'' camp. Every frequency is per year and every probability is a fraction. Every probability of death below is stated from the station''s consequence study, for a person present outdoors and unprotected at the place, and this capstone takes it as given. COMPRESSOR RELEASE: a continuous gas release in the compressor module at 0.00038 per year. Immediate ignition probability 0.15, giving the outcome ''jet or pool fire''; delayed ignition probability 0.37 GIVEN no immediate ignition, a delayed ignition burning as a ''flash fire'' with probability 0.6 or as an ''explosion'' with probability 0.4; otherwise ''no ignition''. SOUR GAS RELEASE: a sour gas release at the inlet manifold at 0.0017 per year, with the branches ''isolated in time'' 0.88 (outcome ''no camp exposure''); or ''isolated late'' 0.08, then ''wind toward the camp'' 0.18 (outcome ''camp exposure'') or ''wind away from the camp'' 0.82 (outcome ''no camp exposure''); or ''not isolated'' 0.04, then ''wind toward the camp'' 0.31 (outcome ''camp exposure'') or ''wind away from the camp'' 0.69 (outcome ''no camp exposure''). PROBABILITY OF DEATH BY PLACE: in the control room ''jet or pool fire'' 0.04, ''flash fire'' 0 and ''explosion'' 0.12; on the compressor deck ''jet or pool fire'' 0.65, ''flash fire'' 1 and ''explosion'' 0.85; in the camp ''camp exposure'' 0.26 and ''explosion'' 0.004. An outcome not listed at a place kills no one there. OPERATOR: 730 hours a year on the compressor deck, 1095 hours in the control room and 2555 hours in the camp. TECHNICIAN: 0.12 of the year on the compressor deck, 400 hours in the control room and 3980 hours in the camp. A year is 8760 hours, and no vulnerability factor is applied. Report six values: the compressor release''s explosion frequency per year; the sour gas release''s camp exposure frequency per year, pooled over every path that reaches it; the LSIR in the control room per year; the LSIR on the compressor deck per year; the operator''s IRPA per year; and the technician''s IRPA per year. Every value to twelve decimals.',
  jsonb_build_array(
    jsonb_build_object('key','ukpokiti_compressor_explosion_frequency_per_yr', 'label','The compressor release''s explosion frequency', 'unit','per year', 'expected',4.7804e-05, 'tol',5e-13),
    jsonb_build_object('key','ukpokiti_camp_exposure_frequency_per_yr', 'label','The sour gas release''s camp exposure frequency, pooled over every path', 'unit','per year', 'expected',4.556e-05, 'tol',5e-13),
    jsonb_build_object('key','ukpokiti_control_room_lsir_per_yr', 'label','The LSIR in the control room', 'unit','per year', 'expected',8.016479999999999e-06, 'tol',5e-13),
    jsonb_build_object('key','ukpokiti_compressor_deck_lsir_per_yr', 'label','The LSIR on the compressor deck', 'unit','per year', 'expected',0.00014938940000000002, 'tol',5e-13),
    jsonb_build_object('key','ukpokiti_operator_irpa_per_yr', 'label','The operator''s IRPA', 'unit','per year', 'expected',1.696191466666667e-05, 'tol',5e-13),
    jsonb_build_object('key','ukpokiti_technician_irpa_per_yr', 'label','The technician''s IRPA', 'unit','per year', 'expected',2.3761559013698634e-05, 'tol',5e-13)
  )
),
(
  'qra', 'intermediate', 'professional',
  'OGINI, a gas terminal beside a village',
  'How many at once: the crew and the village',
  'OGINI, a gas terminal beside a village. Every frequency is per year. The expected number of deaths of each scenario, N, is stated from the terminal''s consequence study and need not be whole; this capstone takes it as given. CREW: ''separator fire'' 0.0043 per year with N = 1.7; ''compressor house explosion'' 0.00061 per year with N = 7.3; ''dropped object during a lift'' 0.022 per year with N = 0.45; ''riser rupture with escalation'' 9.5e-5 per year with N = 21; ''small fire, put out'' 0.034 per year with N = 0. The crew roster is 70 people, each exposed 2184 hours a year. VILLAGE: ''LPG sphere BLEVE'' 3.74e-7 per year with N = 140; ''propane cloud flash fire reaching the village'' 4.53e-6 per year with N = 55; ''H2S cloud reaching the village'' 1.31e-5 per year with N = 10; ''jet fire at the fence'' 4.4e-5 per year with N = 2.5; ''small release, no one reached'' 9.1e-5 per year with N = 0. Compare the village curve with the line the engine calls vrom-establishments, the Purple Book Figure 6.8 line F = 0.001 / N^2 per year for N of 10 or more, on which the three Bevi points lie; and with the point the engine calls r2p2-para-136, the single R2P2 point of 50 or more deaths at 1 in 5000 per year. Read the curve as the frequency of N OR MORE deaths. The step of the village curve that ends at N = 55 is the one the fifth value asks about. Report six values: the crew''s PLL, fatalities per year; the crew''s FAR per 100,000,000 exposed hours; the village''s frequency of ten or more deaths per year; the worst ratio of the village curve to the line; the N from which the village curve lies above the line on the step that ends at N = 55; and the ratio of the village curve to the R2P2 point. The PLL and the frequency to twelve decimals, the FAR, the ratios and the N to six decimals.',
  jsonb_build_array(
    jsonb_build_object('key','ogini_crew_pll_per_yr', 'label','The crew''s PLL', 'unit','fatalities per year', 'expected',0.023658, 'tol',5e-13),
    jsonb_build_object('key','ogini_crew_far', 'label','The crew''s FAR', 'unit','per 100,000,000 exposed hours', 'expected',15.474882260596546, 'tol',5e-07),
    jsonb_build_object('key','ogini_village_frequency_ten_or_more_per_yr', 'label','The village''s frequency of ten or more deaths', 'unit','per year', 'expected',1.8004e-05, 'tol',5e-13),
    jsonb_build_object('key','ogini_village_vrom_max_ratio', 'label','The worst ratio of the village curve to the line', 'unit','ratio', 'expected',14.8346, 'tol',5e-07),
    jsonb_build_object('key','ogini_village_exceedance_from_fatalities', 'label','The N from which the village curve lies above the line on the stated step', 'unit','fatalities', 'expected',14.279886949438497, 'tol',5e-07),
    jsonb_build_object('key','ogini_village_r2p2_point_ratio', 'label','The ratio of the village curve to the R2P2 point', 'unit','ratio', 'expected',0.02452, 'tol',5e-07)
  )
),
(
  'qra', 'advanced', 'expert',
  'EBUGHU, three proposed measures at a gas processing plant',
  'Which measures are reasonably practicable',
  'EBUGHU, a gas processing plant weighing three proposed risk reduction measures by the HSE gross disproportion test. Every PLL reduction is stated from the plant''s own assessment. The values of preventing a fatality are the HSE''s published figures, used here for illustration only: 1336800 GBP at 2003 prices and 1000000 GBP at 2001 prices. DELUGE, a deluge system on the compressor module: a PLL reduction of 0.0031 fatalities per year, a VPF of 1336800 GBP, other harms prevented: ''serious injury'' 0.012 cases a year at 20500 GBP a case and ''slight injury'' 0.05 cases a year at 300 GBP a case, a life of 20 years, a capital cost of 21000 GBP at year 0 and 600 GBP at the end of each year, a disproportion factor of 6, benefits discounted at 0.015 a year and costs at 0.035 a year, every flow at the end of its year. BLAST WALL, a blast wall between the process area and the control building: a PLL reduction of 0.00084 fatalities per year, a VPF of 1000000 GBP, no other harm counted, a life of 25 years, a capital cost of 2900000 GBP at year 0, a disproportion factor of 3, benefits discounted at 0.06 a year and costs at 0.06 a year, the benefit uprated by 0.04 a year, every flow at the end of its year. GAS DETECTION, an upgrade of the gas detection: a PLL reduction of 0.00047 fatalities per year, a VPF of 1336800 GBP, no other harm counted, a life of 15 years, a capital cost of 72300 GBP at year 0 and 4100 GBP at the end of each year, a disproportion factor of 10, undiscounted, every rate zero. Count the fatalities prevented undiscounted, the PLL reduction times the life in years. Report six values: the deluge''s cost to benefit ratio; the deluge''s ICAF, its cost per fatality prevented, in GBP; the largest cost the deluge could carry and stay reasonably practicable, in GBP; the blast wall''s cost to benefit ratio; the blast wall''s ICAF in GBP; and the gas detection''s cost to benefit ratio. The ratios to six decimals, the GBP values to two decimals.',
  jsonb_build_array(
    jsonb_build_object('key','ebughu_deluge_cost_to_benefit_ratio', 'label','The deluge''s cost to benefit ratio', 'unit','ratio', 'expected',0.39042368962287494, 'tol',5e-07),
    jsonb_build_object('key','ebughu_deluge_icaf_gbp', 'label','The deluge''s ICAF, its cost per fatality prevented', 'unit','GBP', 'expected',476249.0642124415, 'tol',0.005),
    jsonb_build_object('key','ebughu_deluge_maximum_reasonably_practicable_cost_gbp', 'label','The largest cost the deluge could carry and stay reasonably practicable', 'unit','GBP', 'expected',453775.3640363327, 'tol',0.005),
    jsonb_build_object('key','ebughu_blast_wall_cost_to_benefit_ratio', 'label','The blast wall''s cost to benefit ratio', 'unit','ratio', 'expected',175.23960830410573, 'tol',5e-07),
    jsonb_build_object('key','ebughu_blast_wall_icaf_gbp', 'label','The blast wall''s ICAF, its cost per fatality prevented', 'unit','GBP', 'expected',138095238.0952381, 'tol',0.005),
    jsonb_build_object('key','ebughu_gas_detection_cost_to_benefit_ratio', 'label','The gas detection''s cost to benefit ratio', 'unit','ratio', 'expected',14.197130015152092, 'tol',5e-07)
  )
)
on conflict (app_slug, tier) do nothing;
